"""Generate fixed instruction cases for counted math; separate candidate only."""
import json,hashlib,re,argparse
from pathlib import Path
from datetime import datetime,timezone
import generate_biwn_movie_cpu as movie
ROOT=movie.ROOT;base=movie.loader.base;RANGES=[(0xe540,0xe61c),(0x1a77c,0x1a7f4)]
def rename(s):return movie.rename(s).replace('biwn_movie_cpu','biwn_atomic_startup_math').replace('BIWN_MOVIE_CPU','BIWN_ATOMIC_STARTUP_MATH')
def emit(row):
    pc=row['address'];nxt=pc+row['size'];asm=row['assembly'];op,_,tail=asm.partition(' ');parts=base.split(tail);code=None
    if op=='movem.w':
        assert asm=='movem.w $4(a7), d0-d3'
        code=[f'CHECK(read_value(&s,s.cpu.registers[15]+{4+2*r}u,2,&v));s.cpu.registers[{r}]=sx16((uint16_t)v);'for r in range(4)]
    elif op=='negx.w':
        r=base.register(parts[0]);code=[f'v=s.cpu.registers[{r}]&0xffffu;u=(s.cpu.sr&0x10u)?1u:0u;{{uint32_t result=(0u-v-u)&0xffffu;unsigned carry=(v!=0)||u,overflow=((v&result)&0x8000u)!=0,zero=(s.cpu.sr&4u)&&!result;put(&s,{r},2,result);s.cpu.sr=(uint16_t)((s.cpu.sr&0xffe0u)|(carry?0x11u:0)|(result&0x8000u?8u:0)|(overflow?2u:0)|(zero?4u:0));}}']
    elif op=='addx.l':
        src,dst=map(base.register,parts);code=[f's.cpu.registers[{dst}]=biwn_addx_long(&s.cpu.sr,s.cpu.registers[{src}],s.cpu.registers[{dst}]);']
    elif op=='exg.l':
        a,b=map(base.register,parts);code=[f'v=s.cpu.registers[{a}];s.cpu.registers[{a}]=s.cpu.registers[{b}];s.cpu.registers[{b}]=v;']
    if code is None:return rename(movie.emit(row))
    return f'  case {hex(pc)}u: /* {asm} */\n   '+'\n   '.join(code+[f's.cpu.pc={hex(nxt)}u;break;'])
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--addx-gate',type=Path,required=True);args=parser.parse_args();gate=json.loads(args.addx_gate.read_text());assert gate['status']=='pass'and gate['failure_count']==0
    addx=args.addx_gate.parent/'candidate.inc';out=ROOT/'verification/atomic-startup-math-generation'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
    session=Path(json.loads((ROOT/'projects/black-ice-white-noise/analysis/current-session.json').read_text())['directory']);stage=(session/'nextstage-68000-candidate.bin').read_bytes();ram=(ROOT/'render-assets/biwn-inventory-baseline.bin').read_bytes();rows=[]
    assert hashlib.sha256(stage).hexdigest()=='52dc987c755b711390dc46353e552b8038a97f9993bbab08947a85d8b033b453'
    for a,b in RANGES:assert stage[a-0x4000:b-0x4000]==ram[a:b];rows+=base.binary_tools.m68k_instructions(ram[a:b],a)[0]
    prefix=rename(base.PREFIX).replace('s->cpu.usp=s->cpu.registers[15];','if(s->cpu.sr&0x2000u)s->cpu.ssp=s->cpu.registers[15];else s->cpu.usp=s->cpu.registers[15];').replace('||(state->sr&0x2000u)','')
    prefix=prefix.replace('switch(s.cpu.pc){','biwn_instruction_observe(&s.cpu);switch(s.cpu.pc){')
    header=rename(base.HEADER).replace('BIWN_INPUT_DISPATCH_CPU_H','BIWN_ATOMIC_STARTUP_MATH_H');header=header.replace('BIWN_ATOMIC_STARTUP_MATH_BAD_PC=7','BIWN_ATOMIC_STARTUP_MATH_BAD_PC=7,BIWN_ATOMIC_STARTUP_MATH_DIVISION_BY_ZERO=9')
    prefix=prefix.replace('/* Generated by', '/* Candidate instruction-boundary math rebuild. Generated by',1)
    text='extern void biwn_instruction_observe(const void *);\n#include <stdint.h>\n'+addx.read_text()+'\n'+prefix+'\n'.join(emit(row)for row in rows)+'\n'+rename(base.SUFFIX)
    # Preserve legacy two-argument ABI with internal body service; no byte writes occur.
    text+='''\nstatic int math_write8(void *context,uint32_t address,uint8_t value){(void)context;(void)address;(void)value;return 1;}
static int math_service(void *context,struct biwn_world_bus *bus,struct biwn_task_cpu *cpu,uint32_t target){(void)context;(void)target;return biwn_atomic_startup_math_body(bus,cpu,math_write8,math_service,0,500000,0);}
static int math_entry_valid(struct biwn_task_cpu *cpu){return cpu&&(cpu->pc==0xe540u||cpu->pc==0xe588u||cpu->pc==0xe60au||cpu->pc==0x1a77cu);}
static int math_legacy_status(int status){return status==0?0:status==1?1:status==2?2:status==9?3:4;}
int biwn_startup_rng_math_cpu_body(struct biwn_world_bus *bus,struct biwn_task_cpu *cpu){if(!math_entry_valid(cpu))return 1;return math_legacy_status(biwn_atomic_startup_math_body(bus,cpu,math_write8,math_service,0,500000,0));}
int biwn_startup_rng_math_cpu_call(struct biwn_world_bus *bus,struct biwn_task_cpu *cpu){if(!math_entry_valid(cpu))return 1;return math_legacy_status(biwn_atomic_startup_math_call(bus,cpu,math_write8,math_service,0,500000,0));}
'''
    (out/'biwn_atomic_startup_math.c').write_text(text);(out/'biwn_atomic_startup_math.h').write_text(header)
    report=dict(status='generated_unverified_atomic_math_candidate',directory=str(out),instructions=len(rows),rows=rows,ranges=RANGES,source_sha256=hashlib.sha256(text.encode()).hexdigest(),addx_local_gate=str(args.addx_gate.resolve()),old_high_level_source_retained=True,new_unique_game_coverage=False,whole_game_complete=False)
    (out/'report.json').write_text(json.dumps(report,indent=2)+'\n');(ROOT/'verification/atomic-startup-math-candidate.json').write_text(json.dumps(report,indent=2)+'\n');print(out)
if __name__=='__main__':main()
